//! Edit intent coordinates remain distinct from original and generated bytes.
use super::*;
use crate::Field;
use crate::document_request::RequestLocation;

pub struct EditRequestLocation<'a>(RequestLocation<'a>);
impl<'a> EditRequestLocation<'a> {
    pub(crate) fn from_report(location: &'a serde_json::Value) -> Self {
        Self(RequestLocation::from_report(location))
    }
    pub fn key(&self) -> &str {
        self.0.key()
    }
    pub fn pointer(&self) -> Field<&str> {
        self.0.pointer()
    }
    /// Textual-plan bytes when available. Typed intent has no textual span.
    pub fn span(&self) -> Option<std::ops::Range<u32>> {
        self.0.span()
    }
}
pub struct EditTarget<'a> {
    result: &'a EditResult,
    index: usize,
    target: Target,
}
impl<'a> EditTarget<'a> {
    pub fn edit(&self) -> &'a Edit {
        &self.result.request.edits[self.index]
    }
    pub fn original_owner(&self) -> JsonView<'a> {
        JsonView {
            source: self.result.original_source(),
            node: self.target.owner,
        }
    }
    pub fn original_member(&self) -> JsonView<'a> {
        JsonView {
            source: self.result.original_source(),
            node: self.target.member,
        }
    }
    pub fn request_location(&self) -> EditRequestLocation<'a> {
        self.result.request_location(self.index)
    }
    pub fn generated_member(&self) -> Field<JsonView<'a>> {
        if self.edit().operation == EditOperation::Remove {
            return Field::Absent;
        }
        let Some(root) = self
            .result
            .catalogue()
            .source(self.result.generated)
            .and_then(|source| source.json().present())
        else {
            return Field::Unavailable("generated source decoding unavailable");
        };
        let mut budget = OperationBudget::new(&self.result.catalogue().limits);
        let mut current = root;
        for token in self
            .edit()
            .owner
            .strip_prefix('/')
            .into_iter()
            .flat_map(|tail| tail.split('/'))
        {
            if !charge(&mut budget.work, token.len() * 4 + 1)
                || !charge(&mut budget.allocation, token.len() * 2)
            {
                return Field::Unavailable("generated target location work limit");
            }
            let token = token.replace("~1", "/").replace("~0", "~");
            current = match field(current, &token, &mut budget) {
                Ok(Some(value)) => value,
                _ => return Field::Unavailable("generated owner unavailable"),
            };
        }
        match field(current, &self.edit().quality, &mut budget) {
            Ok(Some(value)) => Field::Present(value),
            Ok(None) => Field::Absent,
            Err(reason) => Field::Unavailable(reason),
        }
    }
}
impl EditResult {
    pub fn target(&self, index: usize) -> Field<EditTarget<'_>> {
        if index >= self.request.edits.len() {
            return Field::Absent;
        }
        self.targets.get(index).and_then(|target| *target).map_or(
            Field::Unavailable("authored target establishment incomplete"),
            |target| {
                Field::Present(EditTarget {
                    result: self,
                    index,
                    target,
                })
            },
        )
    }
    pub(super) fn request_location(&self, index: usize) -> EditRequestLocation<'_> {
        let located = self
            .request
            .plan
            .as_ref()
            .and_then(|plan| plan.json().present())
            .and_then(|root| root.get("edits").present())
            .and_then(|edits| edits.at(index).present());
        EditRequestLocation(RequestLocation::new(
            &self.request.key,
            format!("/edits/{index}"),
            located,
        ))
    }
    /// Relate a generated replacement occurrence to its owned request value.
    pub fn request_origin(&self, source: JsonView<'_>) -> Field<EditRequestLocation<'_>> {
        let Some(owned) = self.catalogue().source(source.source_id()) else {
            return Field::Unavailable("source belongs to another catalogue");
        };
        if !std::ptr::eq(owned, source.source) {
            return Field::Unavailable("source belongs to another catalogue");
        }
        if source.source_id() != self.generated {
            return Field::Absent;
        }
        let pointer = match source.pointer(self.catalogue().limits.pointer_bytes as u32) {
            Field::Present(pointer) => pointer,
            Field::Unavailable(reason) => return Field::Unavailable(reason),
            Field::Absent => return Field::Absent,
        };
        let mut work = self.catalogue().limits.work;
        for (index, edit) in self.request.edits.iter().enumerate() {
            if edit.operation != EditOperation::Replace {
                continue;
            }
            if !charge(
                &mut work,
                edit.owner.len() * 4 + edit.quality.len() * 4 + pointer.len() + 1,
            ) {
                return Field::Unavailable("edit request origin work limit");
            }
            let member = format!(
                "{}/{}",
                edit.owner,
                edit.quality.replace('~', "~0").replace('/', "~1")
            );
            if pointer == member
                || pointer
                    .strip_prefix(&member)
                    .is_some_and(|suffix| suffix.starts_with('/'))
            {
                let logical = format!("/edits/{index}/value{}", &pointer[member.len()..]);
                if logical.len() > self.catalogue().limits.pointer_bytes {
                    return Field::Unavailable("edit request location limit");
                }
                let located = self
                    .request
                    .plan
                    .as_ref()
                    .and_then(|plan| plan.json().present())
                    .and_then(|root| {
                        crate::report::select_with_budget(root, &logical, &mut work)
                            .ok()
                            .flatten()
                    });
                return Field::Present(EditRequestLocation(RequestLocation::new(
                    &self.request.key,
                    logical,
                    located,
                )));
            }
        }
        Field::Absent
    }
}
